import { Order } from "../domain/order";
import { OrderStatus } from "../domain/order-status";
import { Product } from "../domain/product";

export interface CreateProductInput { id: string; name: string; stock: number; }
export interface PlaceOrderInput { customerId: string; lines: Array<{ productId: string; quantity: number }>; }
export interface OrderDto { id: string; customerId: string; status: OrderStatus; lines: readonly { productId: string; quantity: number }[]; }
export interface ProductDto { id: string; name: string; stock: number; }

export const toOrderDto = (order: Order): OrderDto => ({
  id: order.id, customerId: order.customerId, status: order.status, lines: order.lines,
});

export const toProductDto = (product: Product): ProductDto => ({
  id: product.id, name: product.name, stock: product.availableStock,
});

